package cl.acis.usuarios.service;
import cl.acis.usuarios.dto.*; import cl.acis.usuarios.exception.*; import cl.acis.usuarios.model.*; import cl.acis.usuarios.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.security.SecureRandom; import java.time.*; import java.util.*; import java.util.stream.*;
@Service @RequiredArgsConstructor @Transactional public class UsuarioService {
 private final UsuarioRepository usuarios; private final CodigoRecuperacionRepository codigos; private final PasswordEncoder encoder; private final PoliticaContrasena politica; private final SecureRandom random=new SecureRandom();
 public UsuarioResponse registrar(RegistroRequest r){politica.validar(r.password()); Usuario u=base(r.correo(),r.nombre(),r.password(),Rol.CLIENTE); u.setAceptoTerminosEn(LocalDateTime.now());u.setVersionTerminos("1.0");return dto(usuarios.save(u));}
 public LoginResponse login(LoginRequest r){Usuario u=usuarios.findByCorreoIgnoreCase(r.correo()).orElseThrow(()->new NoAutorizadoException("Correo o contraseña incorrectos")); LocalDateTime ahora=LocalDateTime.now(); if(!u.isActivo())throw new NoAutorizadoException("La cuenta está inactiva"); if(u.getBloqueadoHasta()!=null&&u.getBloqueadoHasta().isAfter(ahora))throw new NoAutorizadoException("La cuenta está bloqueada hasta "+u.getBloqueadoHasta()); if(!encoder.matches(r.password(),u.getPasswordHash())){u.setIntentosFallidos(u.getIntentosFallidos()+1);if(u.getIntentosFallidos()>=5){u.setBloqueadoHasta(ahora.plusMinutes(15));u.setIntentosFallidos(0);}usuarios.save(u);throw new NoAutorizadoException("Correo o contraseña incorrectos");}u.setIntentosFallidos(0);u.setBloqueadoHasta(null);return new LoginResponse(dto(usuarios.save(u)),u.isDebeCambiarContrasena(),requiere(u),null);}
 public List<UsuarioResponse> listar(Rol rol,Boolean activo){List<Usuario> l=rol!=null&&activo!=null?usuarios.findByRolAndActivo(rol,activo):rol!=null?usuarios.findByRol(rol):activo!=null?usuarios.findByActivo(activo):usuarios.findAll();return l.stream().map(this::dto).toList();}
 public UsuarioResponse obtener(Long id){return dto(usuarios.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Usuario no encontrado")));}
 public CrearUsuarioResponse crear(CrearUsuarioRequest r){String p=generarTemporal();Usuario u=base(r.correo(),r.nombre(),p,r.rol());u.setDebeCambiarContrasena(true);return new CrearUsuarioResponse(dto(usuarios.save(u)),p);}
 public UsuarioResponse editar(Long id,EditarUsuarioRequest r){Usuario u=get(id);if(!u.getCorreo().equalsIgnoreCase(r.correo())&&usuarios.existsByCorreoIgnoreCase(r.correo()))throw new ConflictoException("El correo ya está registrado");u.setCorreo(r.correo());u.setNombre(r.nombre());return dto(usuarios.save(u));}
 public UsuarioResponse cambiarRol(Long id,Rol rol,Usuario actor){Usuario u=get(id);if(actor.getId().equals(id))throw new ReglaNegocioException("Un administrador no puede cambiar su propio rol");if(u.getRol()==Rol.ADMINISTRADOR&&rol!=Rol.ADMINISTRADOR&&usuarios.countByRolAndActivo(Rol.ADMINISTRADOR,true)<=1)throw new ReglaNegocioException("Debe existir al menos un administrador activo");u.setRol(rol);return dto(usuarios.save(u));}
 public UsuarioResponse cambiarActivo(Long id,boolean activo,Usuario actor){Usuario u=get(id);if(actor.getId().equals(id)&&!activo)throw new ReglaNegocioException("Un administrador no puede desactivarse a sí mismo");if(u.getRol()==Rol.ADMINISTRADOR&&!activo&&usuarios.countByRolAndActivo(Rol.ADMINISTRADOR,true)<=1)throw new ReglaNegocioException("Debe existir al menos un administrador activo");u.setActivo(activo);return dto(usuarios.save(u));}
 public RecuperarResponse recuperar(String correo){Usuario u=usuarios.findByCorreoIgnoreCase(correo).orElseThrow(()->new RecursoNoEncontradoException("No existe un usuario con ese correo"));CodigoRecuperacion c=new CodigoRecuperacion();c.setUsuario(u);c.setCodigo(String.format("%06d",random.nextInt(1000000)));c.setExpiraEn(LocalDateTime.now().plusMinutes(10));codigos.save(c);return new RecuperarResponse("Código generado. En producción se enviaría por correo.",c.getCodigo());/* TODO producción: enviar código por correo. */}
 public void restablecer(RestablecerRequest r){politica.validar(r.nuevaPassword());Usuario u=usuarios.findByCorreoIgnoreCase(r.correo()).orElseThrow(()->new RecursoNoEncontradoException("Usuario no encontrado"));CodigoRecuperacion c=codigos.findTopByUsuarioAndCodigoAndUsadoFalseOrderByIdDesc(u,r.codigo()).orElseThrow(()->new ReglaNegocioException("Código inválido o ya utilizado"));if(c.getExpiraEn().isBefore(LocalDateTime.now()))throw new ReglaNegocioException("El código expiró");u.setPasswordHash(encoder.encode(r.nuevaPassword()));u.setDebeCambiarContrasena(false);c.setUsado(true);usuarios.save(u);codigos.save(c);}
 public void cambiarPassword(Long id,CambiarPasswordRequest r){Usuario u=get(id);if(!encoder.matches(r.passwordActual(),u.getPasswordHash()))throw new NoAutorizadoException("La contraseña actual no es correcta");politica.validar(r.nuevaPassword());u.setPasswordHash(encoder.encode(r.nuevaPassword()));u.setDebeCambiarContrasena(false);}
 public void cambiarObligatorio(Long id,CambiarPasswordObligatorioRequest r){Usuario u=get(id);if(!u.isDebeCambiarContrasena())throw new ReglaNegocioException("La cuenta no requiere cambio obligatorio");politica.validar(r.nuevaPassword());u.setPasswordHash(encoder.encode(r.nuevaPassword()));u.setDebeCambiarContrasena(false);}
 public UsuarioResponse aceptar(Long id,String version){Usuario u=get(id);u.setAceptoTerminosEn(LocalDateTime.now());u.setVersionTerminos(version);return dto(u);}
 private Usuario base(String c,String n,String p,Rol r){if(usuarios.existsByCorreoIgnoreCase(c))throw new ConflictoException("El correo ya está registrado");Usuario u=new Usuario();u.setCorreo(c);u.setNombre(n);u.setPasswordHash(encoder.encode(p));u.setRol(r);return u;} private Usuario get(Long id){return usuarios.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Usuario no encontrado"));}
 private boolean requiere(Usuario u){return u.getVersionTerminos()==null||u.getAceptoTerminosEn()==null;} private String generarTemporal(){String s="Aa"+random.nextInt(10)+UUID.randomUUID().toString().replace("-","").substring(0,7);return s;}
 public UsuarioResponse dto(Usuario u){return new UsuarioResponse(u.getId(),u.getCorreo(),u.getNombre(),u.getRol(),u.isActivo(),u.isDebeCambiarContrasena(),requiere(u),u.getAceptoTerminosEn(),u.getVersionTerminos(),u.getCreadoEn(),u.getModificadoEn());}
}
